var MSSGHSSAmendUtils = Class.create();
MSSGHSSAmendUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


    formatJSONReadable: function(jsonString, ghssTask) { //MSSCUSTODY-7138

        var amendTaskRec = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_task");
        amendTaskRec.get(ghssTask);

        try {
            // This is a fallback for other cases.
            var jsonObject = JSON.parse(jsonString);
            var formattedJson = JSON.stringify(jsonObject, null, 2);
            amendTaskRec.work_notes = 'Amend Request Sent: \n' + formattedJson.toString();
        } catch (e) {
            // Handle any parsing or splitting errors.
            amendTaskRec.work_notes = 'Error processing Amend Request Sent: \n ' + e.message +
                '\nOriginal string:\n' + jsonString.toString();
            gs.info('Error Received from JSON ' + e);
        }
        amendTaskRec.update();

    }, //MSSCUSTODY-7138

    createOutBoundRecSingleSwitch: function(reqBody, ghssTask, tradeID, tradeLastUpdated) {
        try {
            var outBoundRec = new GlideRecord('x_hsb11_mss_c_ghss_hsbc_ghss_outbound_table');
            outBoundRec.initialize();
            outBoundRec.request_type = 'amend';
            outBoundRec.request_date = new GlideDateTime();
            outBoundRec.request_body = JSON.stringify(reqBody);
            outBoundRec.amend_request_body = encodeURIComponent(JSON.stringify(reqBody));
            outBoundRec.state = 'ready_rpa';
            outBoundRec.sn_task = ghssTask;
            outBoundRec.reference = tradeID;
            outBoundRec.last_update_date_time = tradeLastUpdated;
            outBoundRec.insert();

            this.formatJSONReadable(JSON.stringify(reqBody), ghssTask);

        } catch (ex) {
            gs.info('Error recieved from MSSGHSSAmendutils.createOutBoundRecSingleswitch : ' + ex);
        }

    },

    //MSSCUSTODY-8202 Outbound record for hold and canc
    createOutBoundRecHoldAndCanc: function(reqBody, ghssTask, tradeID, tradeLastUpdated) {
        try {
            var outBoundRec = new GlideRecord('x_hsb11_mss_c_ghss_hsbc_ghss_outbound_table');
            outBoundRec.initialize();
            outBoundRec.request_type = 'amend';
            outBoundRec.request_date = new GlideDateTime();
            outBoundRec.request_body = JSON.stringify(reqBody);
            outBoundRec.amend_request_body = encodeURIComponent(JSON.stringify(reqBody));
            outBoundRec.state = 'ready_rpa';
            outBoundRec.sn_task = ghssTask;
            outBoundRec.reference = tradeID;
            outBoundRec.last_update_date_time = tradeLastUpdated;
            outBoundRec.insert();

            this.formatJSONReadable(JSON.stringify(reqBody), ghssTask);
        } catch (ex) {
            gs.info('Error recieved from MSSGHSSAmendutils.createOutBoundRecHoldAndCanc : ' + ex);
        }

    },

    createOutBoundRecSingleAmend: function(reqBody, ghssTask, makerID, checkerID, tradeID, tradeLastUpdated) {

        /*MSSCUSTODY-5485 && MSSCUSTODY-5494
         Artifacts Included: 
        1) Business Rule: MSS Trade Amendment -  Create Payload
        2) Script Include: x_hsb11_mss_c_proc.MSSCustodyAmendUtils
        3) Method: createPayloadBulkTradeAmendment
		4) Script Include : x_hsb11_mss_c_ghss.MSSCustomeGHSSAmendUtils
		5) Method : createOutBoundRecSingleAmend
        */

        try {
            var outBoundRec = new GlideRecord('x_hsb11_mss_c_ghss_hsbc_ghss_outbound_table');
            outBoundRec.initialize();
            outBoundRec.request_type = 'amend';
            outBoundRec.request_date = new GlideDateTime();
            outBoundRec.request_body = JSON.stringify(reqBody);
            outBoundRec.amend_request_body = encodeURIComponent(JSON.stringify(reqBody));
            outBoundRec.state = 'ready_rpa';
            outBoundRec.sn_task = ghssTask;
            outBoundRec.maker = makerID;
            outBoundRec.checker = checkerID;
            outBoundRec.reference = tradeID;
            outBoundRec.last_update_date_time = tradeLastUpdated;
            outBoundRec.insert();

            //MSSCUSTODY-7138- Update the request sent and response received in task
            this.formatJSONReadable(JSON.stringify(reqBody), ghssTask);
            //MSSCUSTODY-7138- Update the request sent and response received in task

            //MSSCUSTODY-6826
            // Assign payload to custody trade table
            //creating an array as checker_approval for highlighting the fields in checker form which are amended by maker
            // var tradeGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            // tradeGR.addQuery("trade_id", tradeID);
            // tradeGR.query();
            // if (tradeGR.next()) {
            //     // Parse existing trade_audit or initialize as object
            //     var tradeAuditObj = {};
            //     if (!gs.nil(tradeGR.trade_audit)) {
            //         try {
            //             tradeAuditObj = JSON.parse(tradeGR.trade_audit);
            //         } catch (e) {
            //             tradeAuditObj = {};
            //         }
            //     }
            //     // Ensure checker_approval array exists
            //     if (!Array.isArray(tradeAuditObj.checker_approval)) {
            //         tradeAuditObj.checker_approval = [];
            //     }
            // 1. Get handler task created time
            var handlerTaskGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            if (handlerTaskGR.get(ghssTask)) { // ghssTask is the handler task sys_id
                var handlerCreated = handlerTaskGR.sys_created_on;
                var handlerTradeID = handlerTaskGR.trade_id.sys_id.toString();
                var handlerCaseID = handlerTaskGR.trade_case_id.sys_id.toString();

                // Find maker task created just before handler, with type 'Maker', same trade_id and case_id
                var makerTaskGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                makerTaskGR.addQuery('sys_created_on', '<', handlerCreated);
                makerTaskGR.addQuery('trade_task_type', 'Maker'); // Only maker tasks
                makerTaskGR.addQuery('trade_id', handlerTradeID);
                makerTaskGR.addQuery('trade_case_id', handlerCaseID);
                makerTaskGR.orderByDesc('sys_created_on');
                makerTaskGR.setLimit(1);
                makerTaskGR.query();
                var makerTaskID = '';
                if (makerTaskGR.next()) {
                    makerTaskID = makerTaskGR.number.toString();
                }
                // 3. Append maker task ID to payload and push to checker_approval
                var tradeGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                tradeGR.addQuery("trade_id", tradeID);
                tradeGR.query();
                if (tradeGR.next()) {
                    var tradeAuditObj = {};
                    if (!gs.nil(tradeGR.trade_audit)) {
                        try {
                            tradeAuditObj = JSON.parse(tradeGR.trade_audit);
                        } catch (e) {
                            tradeAuditObj = {};
                        }
                    }
                    if (!Array.isArray(tradeAuditObj.checker_approval)) {
                        tradeAuditObj.checker_approval = [];
                    }

                    reqBody.PAYLOAD.task_id = makerTaskID;
                    tradeAuditObj.checker_approval.push(reqBody.PAYLOAD);

                    tradeGR.trade_audit = JSON.stringify(tradeAuditObj);
                    tradeGR.update();
                }
            }
        } catch (e) {
            gs.info('MSSCustomeGHSSAmendUtils with function createOutBoundRecSingleAmend is errored with ' + e.message);
        }

    },


    // MSSCUSTODY-5853 - Added function for updating Outbound Record on receiving EL RPA Amend inbound
    updateOutboundRecord: function(payload, taskSysID, status, ghssMessage, rpaMessage, eventDate, bulkStatus, additionalAttribute) {
        try {

            if (status.toString().indexOf('GHSS_LINK') > -1) {
                var additionalAtt = JSON.parse(additionalAttribute);
                var link_m = additionalAtt.link_maintenance ? additionalAtt.link_maintenance.toString().trim() : "";
                var link_t = additionalAtt.link_type ? additionalAtt.link_type.toString().trim() : "";
            }
            gs.info('Amend Loop 1a ' + payload + " " + taskSysID + " " + status + " " + ghssMessage + " " + rpaMessage + " " + eventDate + " " + bulkStatus);
            var taskGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            taskGR.get(taskSysID);
            gs.info('Amend Task state 1: ' + taskGR.state);

            var outboundGR = new GlideRecord('x_hsb11_mss_c_ghss_hsbc_ghss_outbound_table');
            outboundGR.addEncodedQuery('sn_task.sys_idSTARTSWITH' + taskSysID + '^state=ready_rpa^ORstate=processing_rpa');
            outboundGR.orderByDesc('sys_created_on');
            outboundGR.setLimit(1);
            outboundGR.query();

            if (outboundGR.next()) {
                gs.info('Outbound record found for Task Sys ID: ' + taskSysID);
                outboundGR.response_body = JSON.stringify(payload);
                outboundGR.response_date = eventDate;
                if ((status.toString() == 'GHSS_AMEND_SUCCESS')) {
                    gs.info('Amend Loop 2 ');
                    outboundGR.state = "processed_rpa";
                    outboundGR.response_code = '200';
                    taskGR.state = 3; // closed Complete
                    gs.info('Amend Task state 2: ' + taskGR.state);

                    taskGR.work_notes = ' Request Success - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;

                    // MSSCUSTODY-6893-Start -- Update the bulk active trade count. Count should be reduced as task got completed // MSSCUSTODY-4282
                    var grTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                    if (grTask.get(taskSysID)) {
                        new x_hsb11_mss_c_proc.MSSCustodyBulkUtils().decrementTradeCount(grTask.bulk_id);
                    } // MSSCUSTODY-6893-End

                } else if ((status.toString() == 'GHSS_APPRVL_REQUIRED')) {
                    gs.info('Amend Loop 3');
                    gs.info('Amend Task state 3: ' + taskGR.state);
                    outboundGR.state = "processed_rpa";
                    outboundGR.response_code = '200';

                    gs.info('Amend Task state 3.1: ' + taskGR.state);

                    taskGR.state = 9; //closed Incomplete
                    gs.info('Amend Task state 3.2: ' + taskGR.state);
                    taskGR.work_notes = ' Request Awaiting Checker Approval - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                } else if ((status.toString() == 'GHSS_AMEND_FAIL') || (status.toString() == 'GHSS_APPROVE_FAIL')) {
                    if (bulkStatus.toString() == 'false') {
                        gs.info('Amend Loop 4');
                        outboundGR.state = "error_rpa";
                        taskGR.work_notes = ' Request Fail - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                        taskGR.state = 4; // Set state to closed rejected
                        gs.info('Amend Task state 4: ' + taskGR.state);

                        taskGR.work_notes = ' Request Failed - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                    }

                    if (bulkStatus.toString() == 'true') {

                        if (status.toString() == 'GHSS_AMEND_FAIL') {
                            gs.info('Amend Loop 4.1');
                            outboundGR.state = "error_rpa";
                            taskGR.work_notes = ' Request Fail - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                            taskGR.state = 4; // Set state to closed rejected

                            taskGR.work_notes = ' Request Failed - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                        }

                        if (status.toString() == 'GHSS_APPROVE_FAIL') {

                            gs.info('Amend Loop 4.2');
                            outboundGR.state = "error_rpa";
                            taskGR.work_notes = ' Request Fail - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                            if (taskGR.outcome == 'Amend and CONF') {


                                taskGR.state = 9;

                            } else {


                                taskGR.state = 9;
                            }
                            taskGR.work_notes = ' Request Failed - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;

                        }

                    }
                } else if (status.toString() == 'GHSS_SWITCH_SUCCESS') {
                    gs.info('switch Loop');
                    outboundGR.state = "processed_rpa";
                    outboundGR.response_code = '200';
                    taskGR.state = 3; // Closed Complete


                    taskGR.work_notes = 'Switch Request Success - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                } else if (status.toString() == 'GHSS_SWITCH_FAIL') {
                    outboundGR.state = "error_rpa";
                    taskGR.state = 4; // Closed Rejected


                    taskGR.work_notes = 'Switch Request Failed - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                } else if (status.toString() == 'GHSS_LINK_SUCCESS') {
                    gs.info('link Loop');
                    outboundGR.state = "processed_rpa";
                    outboundGR.response_code = '200';
                    if (!(link_m == 'A' && link_t == 'Self De-Link')) {
                        taskGR.state = 3; // Closed Complete
                    }

                    taskGR.work_notes = 'Link Request Success - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                } else if (status.toString() == 'GHSS_LINK_FAIL') {
                    outboundGR.state = "error_rpa";
                    taskGR.state = 4; // Closed Rejected


                    taskGR.work_notes = 'Link Request Failed - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                } else if (status.toString() == 'GHSS_PAPP_SUCCESS') {
                    outboundGR.state = "processed_rpa";
                    outboundGR.response_code = '200';
                    taskGR.state = 3; // Closed Complete


                    taskGR.work_notes = ' PAPP Approval Request Success - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                } else if (status.toString() == 'GHSS_PAPP_FAIL') {
                    outboundGR.state = "error_rpa";
                    taskGR.state = 4; // Closed Rejected


                    taskGR.work_notes = 'PAPP Approval Request Failed - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                }


            }
            taskGR.update();
            outboundGR.update(); // Update Outbound record

        } catch (e) {
            gs.error('Error in updating GHSS outbound record: ' + e.message);
        }

    },

    type: 'MSSGHSSAmendUtils'
});
